"""Herramientas Nostr mínimas: claves, bech32, eventos y cifrado (NIP-04 / NIP-44).

Estas funciones no saben nada de la web ni del relay: reciben datos y devuelven datos,
por eso se pueden probar solas (ver carpeta tests/).
"""
"""Claves Nostr: generar, convertir a nsec/npub, firmar y acuerdo de clave (ECDH).

Conceptos en simple:
- Clave secreta: 32 bytes al azar. Quien la tenga "es" tú. Se muestra como nsec1….
- Clave pública: se deriva de la secreta. Se comparte. Se muestra como npub1….
  Nostr usa la versión "x-only" (BIP-340): solo la coordenada X del punto, 32 bytes.
- Firma Schnorr (BIP-340): prueba que el dueño de la clave secreta aprobó un mensaje.
- X compartida (ECDH): dos personas obtienen el MISMO secreto combinando su clave
  secreta con la pública del otro. Es la base del cifrado NIP-04 y NIP-44.
"""

import os

from coincurve import PrivateKey, PublicKey, PublicKeyXOnly

from nostr import bech32


class ClaveNostr:
    """Envoltorio de la clave secreta. Su repr NUNCA muestra el secreto (evita filtrarlo en logs)."""

    def __init__(self, secreto: bytes):
        if len(secreto) != 32:
            raise ValueError("la clave secreta debe tener 32 bytes")
        self._privada = PrivateKey(secreto)  # coincurve valida que esté en el rango de la curva
        self.publica: bytes = self._privada.public_key.format()[1:]  # x-only, 32 bytes

    # --- crear ---
    @classmethod
    def generar(cls) -> "ClaveNostr":
        return cls(PrivateKey().secret)

    @classmethod
    def desde_nsec(cls, nsec: str) -> "ClaveNostr":
        return cls(decodificar_nip19(nsec, "nsec"))

    # --- formatos ---
    @property
    def publica_hex(self) -> str:
        return self.publica.hex()

    @property
    def npub(self) -> str:
        return bech32.codificar("npub", self.publica)

    def nsec(self) -> str:
        """Método (no propiedad) a propósito: leer el secreto debe ser una acción explícita."""
        return bech32.codificar("nsec", self._privada.secret)

    def secreto_bytes(self) -> bytes:
        """Solo para guardarla cifrada (almacen.py). No usar en logs ni respuestas."""
        return self._privada.secret

    # --- operaciones ---
    def firmar(self, mensaje32: bytes) -> bytes:
        """Firma Schnorr BIP-340 de un mensaje de 32 bytes (el id del evento). Devuelve 64 bytes."""
        return self._privada.sign_schnorr(mensaje32, os.urandom(32))

    def x_compartida(self, publica_otro: bytes) -> bytes:
        """ECDH: coordenada X SIN hashear del punto secreto·Pública_otro.

        OJO: coincurve.PrivateKey.ecdh() devuelve sha256 del punto, que NO sirve para
        NIP-04 ni NIP-44. Por eso multiplicamos el punto a mano. Anteponemos 0x02 porque
        la pubkey Nostr es x-only; la X del resultado no depende de esa paridad.
        """
        punto = PublicKey(b"\x02" + publica_otro).multiply(self._privada.secret)
        return punto.format()[1:]

    def __repr__(self) -> str:
        return f"<ClaveNostr {self.npub[:12]}…>"

    __str__ = __repr__


def verificar_firma(publica: bytes, mensaje32: bytes, firma: bytes) -> bool:
    """Verifica una firma Schnorr BIP-340. Devuelve False ante cualquier dato inválido."""
    try:
        return PublicKeyXOnly(publica).verify(firma, mensaje32)
    except Exception:
        return False


def decodificar_nip19(texto: str, prefijo_esperado: str) -> bytes:
    """nsec1…/npub1… → 32 bytes, verificando el prefijo. Lanza ValueError si no es válido."""
    prefijo, datos = bech32.decodificar(texto)
    if prefijo != prefijo_esperado:
        raise ValueError(f"se esperaba un {prefijo_esperado}, llegó un {prefijo}")
    if len(datos) != 32:
        raise ValueError("largo inválido")
    return datos
"""Eventos Nostr (NIP-01): calcular el id, firmar y verificar.

Un evento es un JSON con: pubkey, created_at, kind, tags, content, id y sig.
- id  = sha256 de una serialización exacta: [0, pubkey, created_at, kind, tags, content]
        en JSON compacto (sin espacios) y UTF-8 sin escapar.
- sig = firma Schnorr del id con la clave secreta.

Referencia: https://github.com/nostr-protocol/nips/blob/master/01.md
"""

import hashlib
import json
import time

from nostr.claves import ClaveNostr, verificar_firma


def serializar(pubkey_hex: str, created_at: int, kind: int, tags: list, content: str) -> bytes:
    """Serialización NIP-01. `ensure_ascii=False` y separadores compactos dan el mismo
    resultado que JSON.stringify de JavaScript (lo que usa Stacker News para verificar)."""
    datos = [0, pubkey_hex, created_at, kind, tags, content]
    return json.dumps(datos, separators=(",", ":"), ensure_ascii=False).encode("utf-8")


def calcular_id(pubkey_hex: str, created_at: int, kind: int, tags: list, content: str) -> str:
    return hashlib.sha256(serializar(pubkey_hex, created_at, kind, tags, content)).hexdigest()


def firmar_evento(clave: ClaveNostr, kind: int, content: str, tags: list,
                  created_at: int | None = None) -> dict:
    """Crea un evento completo y firmado. Los campos se usan TAL CUAL (no se reordenan tags)."""
    if created_at is None:
        created_at = int(time.time())
    pubkey = clave.publica_hex
    id_hex = calcular_id(pubkey, created_at, kind, tags, content)
    return {
        "id": id_hex,
        "pubkey": pubkey,
        "created_at": created_at,
        "kind": kind,
        "tags": tags,
        "content": content,
        "sig": clave.firmar(bytes.fromhex(id_hex)).hex(),
    }


def verificar_evento(evento: dict) -> bool:
    """True si el id corresponde al contenido y la firma es válida. Nunca lanza excepción."""
    try:
        id_calculado = calcular_id(evento["pubkey"], evento["created_at"], evento["kind"],
                                   evento["tags"], evento["content"])
        if id_calculado != evento["id"]:
            return False
        return verificar_firma(bytes.fromhex(evento["pubkey"]), bytes.fromhex(evento["id"]),
                               bytes.fromhex(evento["sig"]))
    except (KeyError, TypeError, ValueError):
        return False
"""Codificación bech32 (BIP-173), la que usa NIP-19 para nsec1… y npub1….

En simple: convierte bytes en texto legible con un prefijo ("npub", "nsec") y un
checksum de 6 caracteres al final. Si alguien copia mal una letra, el checksum no
cuadra y lo detectamos.

Referencias:
- BIP-173: https://github.com/bitcoin/bips/blob/master/bip-0173.mediawiki
- NIP-19:  https://github.com/nostr-protocol/nips/blob/master/19.md
"""

# Alfabeto de 32 caracteres de bech32 (sin 1, b, i, o para evitar confusiones).
ALFABETO = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"
_GENERADOR = [0x3B6A57B2, 0x26508E6D, 0x1EA119FA, 0x3D4233DD, 0x2A1462B3]


def _polymod(valores: list[int]) -> int:
    """Cálculo del checksum (BCH) definido en BIP-173."""
    chk = 1
    for v in valores:
        tope = chk >> 25
        chk = (chk & 0x1FFFFFF) << 5 ^ v
        for i in range(5):
            chk ^= _GENERADOR[i] if ((tope >> i) & 1) else 0
    return chk


def _expandir_hrp(hrp: str) -> list[int]:
    return [ord(c) >> 5 for c in hrp] + [0] + [ord(c) & 31 for c in hrp]

"""Etapa a: bech32, claves y eventos.

Correr:  .venv\\Scripts\\python -m unittest -v
"""

import unittest

from nostr import bech32
from nostr.claves import ClaveNostr, decodificar_nip19, verificar_firma
from nostr.eventos import calcular_id, firmar_evento, serializar, verificar_evento


class TestNip19(unittest.TestCase):
    """Ejemplos oficiales de NIP-19 (https://github.com/nostr-protocol/nips/blob/master/19.md)."""

    def test_npub_ejemplo_oficial(self):
        npub = "npub10elfcs4fr0l0r8af98jlmgdh9c8tcxjvz9qkw038js35mp4dma8qzvjptg"
        hex_ = "7e7e9c42a91bfef19fa929e5fda1b72e0ebc1a4c1141673e2794234d86addf4e"
        self.assertEqual(decodificar_nip19(npub, "npub").hex(), hex_)
        self.assertEqual(bech32.codificar("npub", bytes.fromhex(hex_)), npub)

    def test_nsec_ejemplo_oficial(self):
        nsec = "nsec1[REDACTADO]"
        hex_ = "67dea2ed018072d675f5415ecfaed7d2597555e202d85b3d65ea4e58d2d92ffa"
        self.assertEqual(decodificar_nip19(nsec, "nsec").hex(), hex_)
        self.assertEqual(ClaveNostr.desde_nsec(nsec).nsec(), nsec)

    def test_letra_mal_copiada_se_detecta(self):
        malo = "npub10elfcs4fr0l0r8af98jlmgdh9c8tcxjvz9qkw038js35mp4dma8qzvjptq"  # última letra cambiada
        with self.assertRaises(ValueError):
            decodificar_nip19(malo, "npub")

    def test_prefijo_equivocado(self):
        npub = "npub10elfcs4fr0l0r8af98jlmgdh9c8tcxjvz9qkw038js35mp4dma8qzvjptg"
        with self.assertRaises(ValueError):
            ClaveNostr.desde_nsec(npub)  # pegar un npub donde va un nsec debe fallar

    def test_espacios_alrededor_se_toleran(self):
        nsec = "  nsec1[REDACTADO]\n"
        self.assertEqual(len(decodificar_nip19(nsec, "nsec")), 32)

