.pasos > li h2::before { content: "Paso " counter(paso) ": "; color: var(--azul); }

.datos { display: grid; grid-template-columns: max-content 1fr; gap: .25rem 1rem; }
.datos dt { font-weight: 700; }
.datos dd { margin: 0; }
.avisos { color: var(--error); font-weight: 600; }
pre { white-space: pre-wrap; overflow-wrap: anywhere; font-size: .85rem; background: #eef1f4; padding: .75rem; }
details summary { cursor: pointer; min-height: 48px; display: flex; align-items: center; color: var(--azul); }

.historial { padding-left: 1.25rem; margin: 0; }
.historial li { margin: .25rem 0; }
.historial .hora { color: var(--texto-2); font-variant-numeric: tabular-nums; }

.oculto-visual {
  position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap;
}
[hidden] { display: none !important; }

.pie { background: var(--azul-oscuro); color: #fff; font-size: .9rem; }
.pie .contenedor { padding-top: 1rem; padding-bottom: 1rem; }
.pie p { margin: 0; }

